import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapWithAutoFill from "../MapWithAutoFill";// Use your map component here
import "./HousePredictionForm.css";

export default function HousePredictionForm() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    location: "",
    area: "",
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    year: "",
    condition: "",
    latitude: null,
    longitude: null,

    hospitalApplicable: "notApplicable",
    hospitalDistance: 0,

    schoolApplicable: "notApplicable",
    schoolDistance: 0,

    railwayApplicable: "notApplicable",
    railwayDistance: 0,

    busApplicable: "notApplicable",
    busDistance: 0,
  });

  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  // Input handler
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  // Callback for map picker autofill
  const handleAutoFill = (data) => {
    setForm((prev) => ({
      ...prev,
      location: data.location || prev.location,
      latitude: data.latitude || prev.latitude,
      longitude: data.longitude || prev.longitude,

      hospitalApplicable: data.hospitalApplicable || "notApplicable",
      hospitalDistance: data.hospitalDistance || 0,

      schoolApplicable: data.schoolApplicable || "notApplicable",
      schoolDistance: data.schoolDistance || 0,

      railwayApplicable: data.railwayApplicable || "notApplicable",
      railwayDistance: data.railwayDistance || 0,

      busApplicable: data.busApplicable || "notApplicable",
      busDistance: data.busDistance || 0,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setResult(undefined);
    setLoading(true);
    try {
      const response = await fetch(
        `${process.env.REACT_APP_BACKEND_URL}/predict/house`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(form),
        }
      );
      const data = await response.json();
      setResult(data.price);
    } catch {
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  const renderFacility = (label, applicableName, distanceName) => (
    <div className="form-group" key={applicableName}>
      <div className="facility-label">{label}</div>
      <div className="facility-radios">
        <label>
          <input
            type="radio"
            name={applicableName}
            value="applicable"
            checked={form[applicableName] === "applicable"}
            onChange={handleChange}
          />
          Applicable
        </label>
        <label>
          <input
            type="radio"
            name={applicableName}
            value="notApplicable"
            checked={form[applicableName] === "notApplicable"}
            onChange={handleChange}
          />
          Not Applicable
        </label>
      </div>
      {form[applicableName] === "applicable" && (
        <input
          type="number"
          min="0"
          step="0.1"
          placeholder={`Distance from ${label.toLowerCase()} (km)`}
          name={distanceName}
          value={form[distanceName]}
          onChange={handleChange}
          required
        />
      )}
    </div>
  );

  return (
    <div className="house-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="house-predict-panels">
        <div className="property-details-card">
          <div className="property-header">
            <span className="icon">
              <img src="/icons/house.png" alt="" />
            </span>
            <span className="property-title">Property Details</span>
          </div>
          <div className="property-desc">
            Enter the details of the house to get an accurate price prediction
          </div>

          <form onSubmit={handleSubmit} className="property-form">
            <div className="form-group">
              <label className="form-label">Location</label>
              <input
                name="location"
                type="text"
                placeholder="e.g., Downtown, Suburb Name"
                value={form.location}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">Choose Location on Map:</label>
              <MapWithAutoFill
                initialLat={form.latitude}
                initialLng={form.longitude}
                onAutoFill={handleAutoFill}
              />
              {form.latitude && form.longitude && (
                <div style={{ fontSize: "0.9em", marginTop: 4 }}>
                  Selected: {form.latitude}, {form.longitude}
                </div>
              )}
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Area (sq ft)</label>
                <input
                  name="area"
                  type="number"
                  min="0"
                  placeholder="1500"
                  value={form.area}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="form-group">
                <label className="form-label">Property Type</label>
                <select
                  name="propertyType"
                  value={form.propertyType}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select type</option>
                  <option>Apartment</option>
                  <option>Villa</option>
                  <option>Independent House</option>
                  <option>Duplex</option>
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Bedrooms</label>
                <select
                  name="bedrooms"
                  value={form.bedrooms}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select</option>
                  {[1, 2, 3, 4, 5].map((b) => (
                    <option key={b}>{b}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Bathrooms</label>
                <select
                  name="bathrooms"
                  value={form.bathrooms}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select</option>
                  {[1, 2, 3, 4, 5].map((b) => (
                    <option key={b}>{b}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Year Built</label>
                <input
                  name="year"
                  type="number"
                  min="1900"
                  max={new Date().getFullYear()}
                  placeholder="2015"
                  value={form.year}
                  onChange={handleChange}
                />
              </div>
              <div className="form-group">
                <label className="form-label">Condition</label>
                <select
                  name="condition"
                  value={form.condition}
                  onChange={handleChange}
                >
                  <option value="">Select condition</option>
                  <option>Excellent</option>
                  <option>Good</option>
                  <option>Needs Renovation</option>
                </select>
              </div>
            </div>

            {/* Facilities */}
            {renderFacility("Hospital", "hospitalApplicable", "hospitalDistance")}
            {renderFacility("School", "schoolApplicable", "schoolDistance")}
            {renderFacility("Railway Station", "railwayApplicable", "railwayDistance")}
            {renderFacility("Bus Stand", "busApplicable", "busDistance")}

            <button className="predict-btn" type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict House Price"}
            </button>
          </form>
        </div>

        {/* Price Output */}
        <div className="price-prediction-card">
          <div className="price-header">
            <span className="price-icon">₹</span>
            <span className="price-title">Price Prediction</span>
          </div>
          <div className="price-desc">
            Your estimated house price will appear here
          </div>
          <div className="price-output">
            {!!result ? (
              <div className="price-result">
                <span className="result-value">₹ {result}</span>
              </div>
            ) : (
              <div className="result-placeholder">
                <span className="result-calc-icon">🧮</span>
                <span>Fill out the form to see your price prediction</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
